				local P = Instance.new("Part") 
				P.Anchored = true 
				P.CanCollide = false 
				P.Name = "Part" 
				P.formFactor = "Custom" 
				P.Size = Vector3.new(0.2,0.2,0.2) 
				P.Locked = true 
				P.TopSurface = 10 
				P.BottomSurface = 10 
				P.FrontSurface = 10 
				P.BackSurface = 10 
