					Build("Speeder") 
				end 

				function RollThatSht(direc) 
					if Roll == 0 then 
						for i = 1, 50 do 
							Roll = (-360 + math.cos(math.pi/50*i) * 360) * direc 
							wait(0.02) 
						end 
						Roll = 0 
					end 
				end 

				function KD(key) 
					if key == "w" then 
						W = true 
					elseif key == "s" then 
						S = true 
					end 

					local rollpls = 0 
					if key == DoublePress[1] and tick() - DoublePress[2] < 0.32 then 
						DoublePress = {nil,0} 
						if key == "a" then 
							rollpls = -1 
						elseif key == "d" then 
							rollpls = 1 
						end 
					end 

					DoublePress = {key,tick()} 
					if rollpls ~= 0 then 
						RollThatSht(rollpls) 
					end 
				end 

				function KU(key) 
					if key == "w" then 
						W = false 
					elseif key == "s" then 
						S = false 
					end 
				end 

