						existingSound.PlaybackSpeed = speed
						existingSound.Volume = Volume
						if looped == "False" then
							existingSound.Looped = false
						elseif looped == "True"	then
							existingSound.Looped = true
						else
							existingSound.Looped = false
						end
						existingSound:Play()
					else
