				fpscaploop = nil
			end

			local fpsCap = 60
			local num = tonumber(args[1]) or 1e6
			if num == "none" then
				return
			elseif num > 0 then
				fpsCap = num
			else
				return notify("Invalid argument", "Please provide a number above 0 or 'none'.")
			end

