	    frame.Size = UDim2.new(1, 0, 1, 0)
	    frame.BackgroundColor3 = Color3.new(0, 0, 0)
	    frame.BackgroundTransparency = 0.2
	    frame.BorderSizePixel = 0
	    frame.Parent = bill

	    local corner = Instance.new("UICorner")
	    corner.CornerRadius = UDim.new(0, 8)
	    corner.Parent = frame

	    local label = Instance.new("TextLabel")
	    label.Size = UDim2.new(1, 0, 1, 0)
	    label.BackgroundTransparency = 1
	    label.Text = ".•° Moderador °○."
	    label.TextColor3 = Color3.fromRGB(100, 200, 255) -- Azul claro
	    label.TextScaled = true
	    label.Font = Enum.Font.GothamBold
	    label.Parent = frame

	    bill.Parent = head
	    Tags[player] = bill
	end

	-- Remove a tag de um jogador
	local function RemoverTag(player)
	    if Tags[player] then
	        Tags[player]:Destroy()
	        Tags[player] = nil
	    end
	end

	-- Atualiza todas as tags com base em TagsAtivadas
	local function AtualizarTags()
	    for _, plr in ipairs(Players:GetPlayers()) do
	        if Moderadores[plr.Name] then
	            if TagsAtivadas then
	                CriarTag(plr)
	            else
	                RemoverTag(plr)
	            end
	        end
	    end
	end

	-- Detecta quando o personagem aparecer
	Players.PlayerAdded:Connect(function(player)
	    player.CharacterAdded:Connect(function()
	        wait(1)
	        if TagsAtivadas and Moderadores[player.Name] then
	            CriarTag(player)
	        end
	    end)
	end)

	-- Para os jogadores já existentes
	for _, plr in ipairs(Players:GetPlayers()) do
	    plr.CharacterAdded:Connect(function()
	        wait(1)
	        if TagsAtivadas and Moderadores[plr.Name] then
	            CriarTag(plr)
