						local Playbackspeed = parent.Parent:WaitForChild("PlayBackSpeed").Text
						local Volume = parent.Parent:WaitForChild("Volume").Text
						local looped = parent.Parent:WaitForChild("Looped").Text
						if SoundId == "" then
