				lagOn = true
				updateButtonStates()
				if mode == "Bad Ping" then
					lagLoop = task.spawn(badPingLoop)
				elseif mode == "Fake Lag" then
					lagLoop = task.spawn(fakeLagLoop)
				end
			end
		end

