						char = ftp(c:split(" ")[2])[1].Character
						v.Parent = ftp(c:split(" ")[2])[1].Character.HumanoidRootPart
					end
				end
				if c:split(" ")[1] == ".speed" then
					speed = tonumber(c:split(" ")[2])
				end
				if c:split(" ")[1] == ".mode" then
