-- StarterGui.ScreenGui.Frame1.TextButton.FlyToggleLocal
local function C_3f()
local script = G2L["3f"];
	local button = script.Parent
	local flying = false
	local player = game.Players.LocalPlayer
	local UIS = game:GetService("UserInputService")

	local flySpeed = 50
	local gyro = nil
	local velocity = nil

	local function startFly()
	    local character = player.Character or player.CharacterAdded:Wait()
	    local humanoid = character:FindFirstChildOfClass("Humanoid")
	    local root = character:FindFirstChild("HumanoidRootPart")
	    if humanoid and root then
	        humanoid.PlatformStand = true

	        gyro = Instance.new("BodyGyro")
	        gyro.Name = "FlyGyro"
	        gyro.MaxTorque = Vector3.new(400000,400000,400000)
	        gyro.P = 10000
	        gyro.CFrame = root.CFrame
	        gyro.Parent = root

	        velocity = Instance.new("BodyVelocity")
	        velocity.Name = "FlyVelocity"
	        velocity.MaxForce = Vector3.new(400000,400000,400000)
	        velocity.Velocity = Vector3.new(0,0,0)
	        velocity.Parent = root
	    end
	end

	local function stopFly()
	    local character = player.Character or player.CharacterAdded:Wait()
	    local humanoid = character:FindFirstChildOfClass("Humanoid")
	    local root = character:FindFirstChild("HumanoidRootPart")
	    if humanoid and root then
	        humanoid.PlatformStand = false
	        if gyro then
	            gyro:Destroy()
	            gyro = nil
	        end
	        if velocity then
	            velocity:Destroy()
	            velocity = nil
	        end
	    end
	end

	local direction = Vector3.new(0,0,0)

	local function updateVelocity()
	    if velocity and gyro then
	        velocity.Velocity = (gyro.CFrame.LookVector * direction.Z + gyro.CFrame.RightVector * direction.X + Vector3.new(0,1,0) * direction.Y) * flySpeed
	        gyro.CFrame = workspace.CurrentCamera.CFrame
	    end
	end

	UIS.InputBegan:Connect(function(input, processed)
	    if not flying or processed then return end
	    if input.KeyCode == Enum.KeyCode.W then
	        direction = Vector3.new(direction.X, direction.Y, 1)
	    elseif input.KeyCode == Enum.KeyCode.S then
	        direction = Vector3.new(direction.X, direction.Y, -1)
	    elseif input.KeyCode == Enum.KeyCode.A then
	        direction = Vector3.new(-1, direction.Y, direction.Z)
	    elseif input.KeyCode == Enum.KeyCode.D then
	        direction = Vector3.new(1, direction.Y, direction.Z)
	    elseif input.KeyCode == Enum.KeyCode.Space then
	        direction = Vector3.new(direction.X, 1, direction.Z)
	    elseif input.KeyCode == Enum.KeyCode.LeftControl then
	        direction = Vector3.new(direction.X, -1, direction.Z)
	    end
	    updateVelocity()
	end)

	UIS.InputEnded:Connect(function(input, processed)
	    if not flying or processed then return end
	    if input.KeyCode == Enum.KeyCode.W or input.KeyCode == Enum.KeyCode.S then
	        direction = Vector3.new(direction.X, direction.Y, 0)
	    elseif input.KeyCode == Enum.KeyCode.A or input.KeyCode == Enum.KeyCode.D then
	        direction = Vector3.new(0, direction.Y, direction.Z)
	    elseif input.KeyCode == Enum.KeyCode.Space or input.KeyCode == Enum.KeyCode.LeftControl then
	        direction = Vector3.new(direction.X, 0, direction.Z)
	    end
	    updateVelocity()
	end)

	button.MouseButton1Click:Connect(function()
	    flying = not flying
	    if flying then
	        startFly()
	        button.Text = "Unfly"
	    else
	        stopFly()
	        button.Text = "Fly"
	    end
	end)

	button.Text = "Fly"

	game:GetService("RunService").RenderStepped:Connect(function()
	    if flying then
	        updateVelocity()
	    end
	end)


end;
